const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['overview','◈','Điều hành'],['missions','◎','Giao việc & Quy trình'],['agents','✧','Đội ngũ & API'],['knowledge','▤','Kho tri thức'],['outputs','↗','Kết quả & Phê duyệt'],['cost','◷','Chi phí & Hiệu quả'],['review','⌘','Đánh giá & Đề xuất']];
const agents=[['Savy','Điều phối','Lập DAG, phân vai, kiểm tra phụ thuộc và quản lý retry.','Reasoning API','📋'],['Quill','Chiến lược','Tổng hợp tài liệu, trích dẫn nguồn và chuẩn hóa brief.','Search + Document API','✍'],['PY','Nội dung','Viết nội dung đa kênh, tạo biến thể và lịch xuất bản.','Text API','✎'],['WickedBoy','Sáng tạo','Xây moodboard, prompt ảnh và đặc tả thiết kế.','Image API','◈'],['Gantt','Dữ liệu & Ngân sách','Tính toán ngân sách, kiểm tra số liệu và tạo file.','Code + Spreadsheet tools','▥'],['Vigil','Kiểm định độc lập','Đối chiếu bằng chứng, chỉ rõ lỗi và yêu cầu sửa.','Reviewer API','⛨'],['WickedMan','Phê duyệt','Đánh giá rubric, tổng hợp rủi ro và trình người duyệt.','Reasoning API','✧']];
const scenarios={marketing:['Ra mắt dịch vụ AI Office cho SME','Marketing','Tạo 60 khách hàng tiềm năng đủ điều kiện trong 30 ngày với ngân sách 50 triệu đồng. Ưu tiên doanh nghiệp 20–100 nhân sự; không cam kết doanh thu.','IMC 30 ngày, 5 caption, 1 kịch bản video, ngân sách và checklist tracking.'],it:['Xây cổng tiếp nhận khách hàng','IT','Thiết kế cổng nhận lead có xác thực, phân quyền và chống gửi trùng; tích hợp CRM qua webhook trong môi trường thử nghiệm.','Đặc tả API, tiêu chí nghiệm thu, threat model và kế hoạch kiểm thử.'],finance:['Đối soát ngân sách chiến dịch','Kế toán','Lập kế hoạch đối soát chi phí chiến dịch 50 triệu. Chỉ dùng dữ liệu giả lập; phát hiện trùng hóa đơn và vượt ngân sách.','Bảng ngân sách, quy tắc đối soát và danh sách ngoại lệ.'],hr:['Đào tạo đội triển khai AI Office','HR','Xây chương trình onboarding 30 ngày cho 2 nhân sự vận hành AI. Không dùng dữ liệu ứng viên thật.','Lộ trình 30 ngày, ma trận kỹ năng và checklist đánh giá.']};
const docs={
'01 · Creative brief':`MỤC TIÊU & GIẢ ĐỊNH\nDịch vụ mẫu: KCC AI Office cho SME 20–100 nhân sự.\nMục tiêu thử nghiệm: 60 lead đạt chuẩn / 30 ngày. Đây là mục tiêu đặt ra, không phải dự báo.\nLead đạt chuẩn: có tên doanh nghiệp, nhu cầu cụ thể, người phụ trách và đồng ý được liên hệ.\n\nTHÔNG ĐIỆP\n“Giao một mục tiêu. Nhận một bộ kết quả có người kiểm tra.”\nKhông tuyên bố thay thế nhân sự hoặc bảo đảm tiết kiệm 86%.\n\nINSIGHT — GIẢ THUYẾT CẦN PHỎNG VẤN\nChủ doanh nghiệp đã thử chatbot nhưng vẫn phải tự ghép kết quả và kiểm tra chất lượng.\nKiểm chứng bằng 5 cuộc phỏng vấn trước khi mở rộng chi tiêu.\n\nPHỄU\nNội dung giáo dục → landing demo → form có đồng ý liên hệ → tư vấn 20 phút → pilot có tiêu chí nghiệm thu.\n\nTIÊU CHÍ ĐẠT\nĐủ đầu ra; mọi số liệu có nguồn hoặc nhãn giả định; tổng ngân sách = 50 triệu; không xuất bản trước khi người dùng duyệt.`,
'02 · Kế hoạch 30 ngày':`NGÀY 1–5 · CHUẨN BỊ\nQuill: 5 phỏng vấn, xác nhận insight và phân khúc.\nIT: form nhận lead, consent, webhook chống trùng.\nVigil: kiểm tra claims và thử form trên thiết bị di động.\nCổng chặn: chưa có tracking hoạt động → chưa chạy quảng cáo.\n\nNGÀY 6–12 · THỬ NGHIỆM\nPY: 5 bài social + 1 video + 2 biến thể CTA.\nGantt: chia thử nghiệm theo kênh, đặt giới hạn chi tiêu hằng ngày.\nĐánh giá theo lead đạt chuẩn, không chỉ theo lượt click.\n\nNGÀY 13–23 · TỐI ƯU\nLoại nội dung có nhiều lead không phù hợp.\nKhông tự tăng ngân sách; trình đề xuất kèm bằng chứng.\n\nNGÀY 24–30 · TỔNG KẾT\nĐối soát CRM và chi phí. Báo cáo lead hợp lệ, CPL, tỷ lệ hẹn tư vấn.\nPhân biệt số liệu đo được với suy luận; đề xuất pilot tiếp theo.`,
'03 · Bộ nội dung & Visual':`5 CAPTION MẪU\n1. Bạn giao việc cho AI, hay đang làm người ghép bài cho AI? Xem cách một brief đi qua thực thi, kiểm tra và phê duyệt trong bản demo KCC AI Office.\n2. Một kế hoạch tốt cần nhiều hơn một câu trả lời hay. Cần ngân sách khớp, nguồn rõ và người chịu trách nhiệm. Đặt lịch xem quy trình mẫu 20 phút.\n3. Content có rồi. Nhưng tracking đã sẵn sàng chưa? Xem checklist ra mắt chiến dịch của đội AI Office.\n4. AI làm bản nháp. Bạn giữ quyền quyết định. Mỗi kết quả quan trọng đều có bước duyệt trước khi gửi hoặc xuất bản.\n5. Chọn một quy trình lặp lại trong tuần của bạn. Chúng tôi cùng bạn thiết kế pilot có tiêu chí đo lường cụ thể.\n\nVIDEO 30 GIÂY\n0–5s: Nhiều cửa sổ chat, file rời rạc. “AI trả lời nhanh. Ai kiểm tra đầu ra?”\n5–15s: Một brief tách thành các hạng mục có người phụ trách.\n15–23s: QA phát hiện thiếu tracking, trả về đúng agent, hiển thị bản sửa.\n23–30s: Người quản lý duyệt gói kết quả. CTA: “Xem demo quy trình của bạn.”\n\nVISUAL BRIEF\nTông indigo, nền sáng; sơ đồ brief → thực thi → QA → duyệt.\nẢnh minh họa phải ghi “mô phỏng”. Không dùng logo khách hàng chưa được phép.\nĐịnh dạng: 1080×1350 và 1080×1920; tương phản đủ đọc trên điện thoại.\nĐầu ra này là đặc tả, chưa phải ảnh đã render.`,
'04 · Ngân sách & Đo lường':`NGÂN SÁCH MẪU — 50.000.000 VND\nPaid social: 20.000.000 (40%)\nSearch intent: 12.000.000 (24%)\nContent & thiết kế: 10.000.000 (20%)\nDự phòng: 8.000.000 (16%)\nTỔNG: 50.000.000 (100%)\n\n60 lead đạt chuẩn → CPL toàn bộ mục tiêu = 833.333 VND.\nNếu chỉ 30 lead: 1.666.667 VND/lead. Nếu 90 lead: 555.556 VND/lead.\nCác mức trên là phép chia kịch bản, không phải dự báo thị trường.\n\nTRACKING\nUTM: source / medium / campaign / content.\nEvents: landing_view → form_submit → lead_qualified → meeting_booked.\nChống trùng bằng lead_id; không gửi email/số điện thoại vào analytics công khai.\nCPL = chi phí đã đối soát / số lead hợp lệ không trùng.\nChưa có doanh thu và biên lợi nhuận thực tế → chưa kết luận ROI/ROAS.`,
'05 · IT · Hợp đồng API & Kiểm thử':`POST /leads — HỢP ĐỒNG ĐỀ XUẤT\nInput: company, business_email, need, consent, idempotency_key.\nServer kiểm tra schema, giới hạn tốc độ, chuẩn hóa dữ liệu và kiểm tra chống trùng.\nSecrets đặt ở server; trình duyệt không giữ API key provider.\n\nCHECKLIST NGHIỆM THU\n[ ] Chưa đồng ý liên hệ → không tạo lead marketing.\n[ ] Gửi lại cùng idempotency_key → không tạo bản ghi trùng.\n[ ] Webhook lỗi → retry có backoff và hàng đợi lỗi.\n[ ] Người dùng phòng khác không đọc được tài liệu bị hạn chế.\n[ ] Log che email, token và nội dung nhạy cảm.\n[ ] Xóa dữ liệu theo chính sách lưu trữ của doanh nghiệp.\n\nĐây là đặc tả mô phỏng; chưa có backend được triển khai hoặc penetration test.`,
'06 · HR · Onboarding 30 ngày':`VAI TRÒ MẪU: NGƯỜI VẬN HÀNH AI OFFICE\nTuần 1: nhận diện Demo/Live, viết brief, gắn tài liệu và xác định quyền truy cập.\nTuần 2: theo dõi workflow, xử lý thiếu nguồn, lỗi API, retry và phiên bản đầu ra.\nTuần 3: đọc biên bản QA, yêu cầu sửa cụ thể, kiểm tra ngân sách và thông tin nhạy cảm.\nTuần 4: vận hành pilot có giám sát; tổng kết lỗi và thời gian sửa thực tế.\n\nNGHIỆM THU\nHoàn thành 3 tình huống sandbox, không gửi dữ liệu thật sai nơi, không xuất bản khi chưa duyệt.\nĐiểm đánh giá gắn với hành vi quan sát được; người quản lý xác nhận.\nKhông dùng AI tự quyết định tuyển dụng hoặc đánh giá nhân sự.`,
'07 · Biên bản QA & Quyết định':`VÒNG 1 — TRẢ VỀ\n1. CPL trước đó chỉ chia chi phí quảng cáo, chưa tính chi phí sản xuất.\n2. Claim “giảm 86% token” không có baseline đối chứng.\n3. Thiếu lead_qualified và điều kiện consent.\n\nVÒNG 2 — SỬA\nGantt đổi CPL sang 50 triệu / 60 lead; thêm kịch bản 30/90 lead.\nPY xóa claim chưa kiểm chứng; dùng mô tả quy trình.\nIT thêm lead_qualified, consent và idempotency.\n\nRUBRIC MÔ PHỎNG\nĐủ đầu ra 28/30; nhất quán số liệu 24/25; truy xuất bằng chứng 21/25; khả năng triển khai 17/20 = 90/100.\nĐiểm do kịch bản gán để minh họa, không phải đánh giá độc lập của API.\n\nQUYẾT ĐỊNH\nĐủ điều kiện trình người dùng duyệt BẢN NHÁP.\nChưa được chạy quảng cáo, gửi email, giải ngân hay đăng bài.\nCần kiểm chứng insight, kết nối tracking và xác nhận thông tin sản phẩm trước khi triển khai.`};
let state={page:'overview',phase:0,scenario:'marketing',approved:false,fault:'none',fixed:false,files:[],draft:null};
const title=()=>state.draft?.title||scenarios[state.scenario][0];
const pill=(s,c='')=>`<span class="pill ${c}">${s}</span>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function go(page){state.page=page;render();window.scrollTo(0,0)}
function modal(title,body){$('#detail-content').innerHTML=`<p class="eyebrow">KCC / REVIEW DESK</p><h2>${escapeHtml(title)}</h2><div class="document">${escapeHtml(body)}</div>`;$('#detail').showModal()}
function render(){ $('#nav').innerHTML=pages.map(([id,icon,label])=>`<button class="${state.page===id?'active':''}" data-page="${id}">${icon} &nbsp; ${label}</button>`).join('');$('#breadcrumb').textContent=pages.find(p=>p[0]===state.page)[2]; const views={overview,missions,agents:agentView,knowledge,outputs,cost,review};$('#view').innerHTML=views[state.page]();bind(); }
function heading(kicker,name,sub,action=''){return `<div class="heading"><div><p class="eyebrow">${kicker}</p><h1>${name}</h1><p class="lead">${sub}</p></div>${action}</div>`}
function overview(){return heading('MISSION CONTROL','Một mục tiêu. Cả đội cùng tiến.','Từ yêu cầu ban đầu đến bộ kết quả có thể kiểm tra và bàn giao.','<button class="primary" data-page="missions">＋ Tạo nhiệm vụ</button>')+`<div class="hero"><p class="eyebrow">KỊCH BẢN NỔI BẬT / 01</p><h2>Ra mắt AI Office.<br>Phối hợp cả bốn phòng ban.</h2><p>Marketing tạo chiến dịch · IT chuẩn bị tracking · Kế toán kiểm tra ngân sách · HR chuẩn hóa vận hành. Mọi đầu ra đi qua QA và người duyệt.</p><button data-scenario="marketing">Khám phá quy trình &nbsp; ↗</button></div><div class="stats">${[['Phòng ban phối hợp','04','Marketing · IT · Kế toán · HR'],['Vai trò chuyên môn','07','Phân vai theo công việc'],['Hạng mục bàn giao','07','Có nội dung mẫu để xem'],['Quyền quyết định','Bạn','Duyệt trước hành động bên ngoài']].map(x=>`<div class="stat"><label>${x[0]}</label><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div><div class="grid"><div class="card"><div class="card-head"><h2>Quy trình được thiết kế để hoàn tất</h2>${pill('3 TUYẾN')}</div>${[['01','Làm rõ mục tiêu','Đầu vào, đầu ra, ràng buộc, tài liệu và tiêu chí nghiệm thu.'],['02','Điều phối theo phụ thuộc','Brief trước, nội dung sau; các việc độc lập chạy song song.'],['03','QA → sửa → duyệt','Lưu lỗi, bản sửa, bằng chứng và quyết định của người dùng.']].map(x=>`<div class="step"><b>${x[0]}</b><div><h3>${x[1]}</h3><p>${x[2]}</p></div></div>`).join('')}</div><div class="card"><div class="card-head"><h2>Cần bạn quyết định</h2>${pill('SANDBOX','orange')}</div><h3>${escapeHtml(title())}</h3><p class="muted">${state.phase>=4?'Gói kết quả đã sẵn sàng. Xem QA và duyệt bản nháp.':'Chạy kịch bản để quan sát cách các agent xử lý và kiểm tra công việc.'}</p><button data-page="${state.phase>=4?'outputs':'missions'}">${state.phase>=4?'Mở bàn phê duyệt':'Bắt đầu mô phỏng'} →</button><div class="section"><small>Đề xuất quan trọng nhất</small><p>Hiển thị Demo / Live trên mọi màn hình và tách số liệu giả lập khỏi số liệu đo được.</p><button data-page="review">Xem toàn bộ đánh giá ↗</button></div></div></div>`}
function missions(){let s=scenarios[state.scenario],d=state.draft;return heading('WORKFLOW STUDIO','Giao mục tiêu, xem cách hoàn thành.','Kịch bản có sẵn minh họa năng lực khi đầy đủ công cụ. Không gọi API thật.')+`<div class="toolbar">${Object.entries(scenarios).map(([id,v])=>`<button data-scenario="${id}" class="${state.scenario===id?'active':''}">${v[1]}</button>`).join('')}</div><div class="grid"><div class="card"><h2>01 / Brief công việc</h2><form id="brief"><div class="form-grid"><label class="full">Tên nhiệm vụ<input required name="title" value="${escapeHtml(d?.title||s[0])}"></label><label class="full">Mục tiêu & ràng buộc<textarea required name="goal">${escapeHtml(d?.goal||s[2])}</textarea></label><label class="full">Đầu ra nghiệm thu<textarea required name="expected">${escapeHtml(d?.expected||s[3])}</textarea></label><label>Trần chi phí API giả lập (USD)<input required name="budget" type="number" min="0.1" step="0.1" value="${d?.budget||2}"></label><label>Tình huống thử<select name="fault"><option value="none">Luồng bình thường</option><option value="rate">API giới hạn tốc độ (429)</option><option value="missing">Thiếu tài liệu bắt buộc</option></select></label></div><p class="hint">Chỉnh brief để lưu yêu cầu. Bộ đầu ra minh họa cố định cho chiến dịch AI Office; không tự sinh nội dung theo brief mới.</p><button class="primary" ${state.phase===1||state.phase===2?'disabled':''}>▶ Chạy mô phỏng</button></form></div><div class="card"><div class="card-head"><h2>02 / Tiến trình</h2>${pill(state.phase>=4?'CHỜ BẠN DUYỆT':state.phase?'ĐANG MÔ PHỎNG':'SẴN SÀNG',state.phase>=4?'orange':'')}</div><p>Quill → Savy → PY / WickedBoy / Gantt → Vigil → WickedMan → Bạn</p><div class="progress"><i style="width:${state.phase*25}%"></i></div><div id="run-status">${runStatus()}</div><div class="section"><h3>Cổng kiểm soát</h3><p class="hint">✓ Chặn brief rỗng<br>✓ Không vượt trần chi phí giả lập<br>✓ Lỗi không được báo thành công<br>✓ QA trả về sửa trước phê duyệt<br>✓ Không tự đăng bài hoặc gửi dữ liệu</p></div></div></div><div class="section card"><h2>Phân công xuyên phòng ban</h2>${[['Marketing','Creative brief, content, media plan','Quill · PY · WickedBoy'],['IT','Form, API contract, tracking, kiểm thử','Savy + công cụ code (đề xuất)'],['Kế toán','Tổng ngân sách và ngoại lệ','Gantt + công cụ bảng tính (đề xuất)'],['HR','Onboarding & quy trình duyệt','Quill + kho tài liệu (đề xuất)']].map(x=>`<div class="row"><span class="avatar">${x[0][0]}</span><div class="row-content"><h3>${x[0]}</h3><small>${x[1]}</small></div><small>${x[2]}</small></div>`).join('')}</div>`}
function runStatus(){if(state.phase===0)return '<p class="muted">Chưa chạy. Bắt đầu bằng một brief có tiêu chí rõ ràng.</p>';if(state.phase===1)return '<p>① Đọc brief và xác định phụ thuộc…</p>';if(state.phase===2)return '<p>② Các vai trò chuyên môn tạo bản nháp…</p>';if(state.phase===3)return `<div class="notice">${state.fault==='missing'&&!state.fixed?'Thiếu tài liệu: dừng ở bước xác minh đầu vào.':state.fault==='rate'&&!state.fixed?'API 429: đã dừng nhánh lỗi, giữ các đầu ra đã hoàn tất.':'Vigil trả về: thiếu nguồn cho claim tiết kiệm và chưa tính đủ CPL.'}</div><button id="fix">${state.fault==='missing'&&!state.fixed?'Gắn tài liệu mẫu & tiếp tục':state.fault==='rate'&&!state.fixed?'Mô phỏng fallback & tiếp tục':'Sửa theo QA & chạy lại kiểm định'}</button>`;return `<p class="check">✓ Đã sửa 3 vấn đề QA trong kịch bản mẫu.</p><p>07 tài liệu minh họa sẵn sàng. Quyết định cuối thuộc về bạn.</p><button class="primary" data-page="outputs">Xem kết quả & duyệt →</button>`}
function agentView(){return heading('AGENT ROSTER','Đúng công cụ. Đúng vai trò.','Thêm API mở rộng khả năng; chất lượng vẫn cần được kiểm chứng bằng đầu ra.')+`<div class="notice">Bản này mô phỏng kiến trúc đầy đủ. Các kết nối dưới đây là đề xuất, chưa được cài vào app gốc. Không nhập API key vào prototype.</div><div class="agent-grid">${agents.map((a,i)=>`<div class="card"><div class="card-head"><span class="avatar">${a[5]}</span>${pill(i===5?'TUYẾN 2':i===6?'TUYẾN 3':'TUYẾN 1')}</div><h2>${a[0]}</h2><small>${a[1]}</small><p>${a[2]}</p><div class="hint">${a[3]} · Chưa kết nối</div><button data-agent="${i}">Xem quyền & đầu ra ↗</button></div>`).join('')}</div><div class="card section"><h2>Ma trận công cụ cần bổ sung</h2><div class="table-wrap"><table><tr><th>NHÓM CÔNG CỤ</th><th>KHẢ NĂNG MỞ KHÓA</th><th>ĐIỀU KIỆN</th></tr>${[['Search / Fetch','Nghiên cứu có nguồn và thời điểm truy xuất','Chặn nội dung web điều khiển agent'],['Document / OCR / RAG','Đọc file và dẫn đúng trang / ô','ACL theo tài liệu, kiểm tra kết quả trích xuất'],['Code sandbox','Tính toán, test, tạo file có thể tải','Cô lập môi trường, giới hạn thời gian'],['Image / Media','Ảnh thật từ brief, phiên bản và preview','Lưu prompt, nguồn và quyền sử dụng'],['CRM / Drive / Email','Bàn giao kết quả vào công việc thật','Dry-run và người dùng duyệt trước khi ghi'],['Queue / Scheduler','Chạy dài, phục hồi và chạy theo lịch','Idempotency, giới hạn retry và cảnh báo']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</table></div></div>`}
function knowledge(){return heading('KNOWLEDGE HUB','Ngữ cảnh đủ. Quyền truy cập rõ.','Minh họa cách giao tài liệu cho đúng agent và theo dõi nguồn.')+`<div class="notice">File chọn ở đây chỉ được hiển thị tên và kích thước trong bộ nhớ tab. Prototype không upload, không đọc hay lập chỉ mục nội dung file.</div><div class="card"><h2>Tài liệu đầu vào</h2><label>Chọn file để thử giao diện<input id="files" type="file" multiple></label>${state.files.map(f=>`<div class="row"><span class="avatar">▤</span><div class="row-content"><h3>${escapeHtml(f.name)}</h3><small>${(f.size/1024).toFixed(1)} KB · Chưa xử lý</small></div>${pill('CHỈ XEM TÊN','orange')}</div>`).join('')}<div class="table-wrap section"><table><tr><th>TÀI LIỆU MẪU</th><th>AI ĐƯỢC ĐỌC</th><th>TÌNH TRẠNG</th></tr>${[['Brand brief v1','Quill, PY, WickedBoy, Vigil','Giả định trong kịch bản'],['Ngân sách 50 triệu','Gantt, Vigil, WickedMan','Số liệu giả lập'],['Consent & tracking spec','IT, Vigil','Đặc tả đề xuất'],['Hồ sơ nhân sự thật','Không agent nào','Không được cung cấp']].map(x=>`<tr>${x.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</table></div></div><div class="card section"><h2>Những gì backend thật phải chứng minh</h2><p class="muted">Mỗi trích dẫn mở đúng đoạn nguồn; thay tài liệu làm mất hiệu lực kết quả cũ; thay quyền truy cập được áp dụng ngay cả với cache; file độc hại hoặc chỉ dẫn bên trong tài liệu không được vượt quyền của agent.</p></div>`}
function outputs(){return heading('REVIEW DESK','Kết quả để bạn ra quyết định.','Xem nội dung, biên bản kiểm tra và điều kiện trước khi bàn giao.')+(state.phase<4?`<div class="card empty"><h2>Chưa có phiên mô phỏng hoàn tất</h2><p>Chạy quy trình, xử lý điểm chặn QA rồi quay lại bàn duyệt.</p><button class="primary" data-page="missions">Mở quy trình →</button></div>`:`<div class="grid"><div class="card"><div class="card-head"><h2>Gói bàn giao / AI Office Launch</h2>${pill('7 TÀI LIỆU','green')}</div><p class="hint">Nội dung mẫu do Codex soạn cho kịch bản chiến dịch. Chưa dùng dữ liệu doanh nghiệp hoặc API bên ngoài.</p>${Object.keys(docs).map((k,i)=>`<button class="artifact" data-doc="${i}">▤ &nbsp; ${k}<small>${i===6?'Vòng 1 trả về → bản sửa → quyết định có điều kiện':'Mở nội dung đầy đủ và kiểm tra đầu ra'} &nbsp; ↗</small></button>`).join('')}<button id="export">↓ Tải toàn bộ gói Markdown</button></div><div><div class="card"><p class="eyebrow">QA SCORE / MINH HỌA</p><div class="score">90<span style="font-size:18px;color:#989db3;letter-spacing:0"> / 100</span></div><p class="muted">Điểm được gán trong kịch bản, không phải điểm chấm của một API độc lập.</p>${pill(state.approved?'BẠN ĐÃ DUYỆT BẢN NHÁP':'CHỜ NGƯỜI DÙNG DUYỆT',state.approved?'green':'orange')}<p>Điều kiện còn mở: xác nhận sản phẩm, kiểm chứng insight và thử tracking trước khi triển khai.</p><button class="primary" id="approve" ${state.approved?'disabled':''}>Duyệt bản nháp trong sandbox</button><button id="reject" style="margin-top:10px">Trả về sửa</button></div><div class="notice section">Duyệt ở đây chỉ thay đổi trạng thái trong tab. Không chạy quảng cáo, giải ngân, gửi email hoặc xuất bản.</div></div></div>`)}
function cost(){return heading('COST INTELLIGENCE','Đo chi phí. Đừng đo bằng cảm giác.','Số liệu minh họa kiến trúc báo cáo, không phải usage hoặc báo giá API hiện hành.')+`<div class="stats">${[['Chi phí API thật','$0','Prototype không gọi API'],['Chi phí kịch bản','$0.42','Giá trị minh họa cố định'],['Trần mỗi nhiệm vụ',`$${state.draft?.budget||2}`,'Được kiểm tra trước khi chạy'],['Tiết kiệm đo được','N/A','Chưa có baseline đối chứng']].map(x=>`<div class="stat"><label>${x[0]}</label><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div><div class="grid"><div class="card"><h2>Phân bổ giả lập theo bước</h2><div class="bar"><span style="width:20%"></span><span style="width:42%"></span><span style="width:26%"></span><span style="width:12%"></span></div>${[['Brief & điều phối','$0.08'],['Tạo các đầu ra','$0.18'],['QA & sửa lại','$0.11'],['Tổng hợp & duyệt','$0.05']].map(x=>`<div class="row"><div class="row-content">${x[0]}</div><strong>${x[1]}</strong></div>`).join('')}<p class="hint">Tổng $0.42 bao gồm retry giả lập. Không dùng bảng giá này để quyết định mua API.</p></div><div class="card"><h2>Đo hiệu quả đúng cách</h2><p>Chạy cùng một bộ tác vụ với và không có điều phối. Giữ tiêu chí chất lượng cố định, đo tokens từ provider, số lần sửa, thời gian người duyệt và tỷ lệ hoàn tất.</p><p class="muted">Báo cáo riêng tiền API đã trả, thời gian nhân sự ước tính và chi phí thực tế đã tránh được. Không cộng các khái niệm này thành một con số “Saved” duy nhất.</p></div></div>`}
const findings=[['P0','Demo / Live chưa rõ xuyên suốt','Cài đặt xác nhận không có key là Demo. Tuy nhiên luồng thử vẫn báo ĐẠT, token và “đã lưu Drive”.','Gắn mode lên mỗi run, artifact và metric. Demo không được tăng thống kê thật.'],['P0','Nhiệm vụ rỗng vẫn chạy','Ở modal Tạo Tùy Chỉnh, không nhập nội dung rồi bấm chạy: app tự dùng nhiệm vụ mặc định và tạo MKT-G1-BC-B03.','Bắt buộc nội dung hoặc có nút “Chạy ví dụ” tách riêng.'],['P0','Đầu ra và bằng chứng phải mở được','Nhật ký ghi QA yêu cầu sửa rồi chốt ĐẠT; chưa thấy bằng chứng bản sửa tại nhật ký đã quan sát.','Lưu artifact version, lỗi QA, diff bản sửa và liên kết tải thật; chặn duyệt khi lỗi còn mở.'],['P1','Saved không nhất quán về cơ sở tính','Màn Chi phí nêu $15/h nhưng bảng vị trí hiển thị $70–95/h; có tiết kiệm cố định 86%.','Cho xem công thức từng run, nhãn ước tính, baseline và dữ liệu nguồn.'],['P1','Dashboard bảo mật thiếu nguồn đo','Màn hình hiện Health 92, 28 scans và danh sách cổng khi chưa thực hiện scan.','Ghi “dữ liệu mẫu” hoặc bổ sung collector, thời điểm đo, phạm vi và bằng chứng. Chưa xác minh đây là lỗ hổng thật.'],['P1','Tách agent khỏi công cụ thực thi','Có nhiều provider và persona nhưng chưa chứng minh tạo file, ảnh hay thao tác hệ thống thật.','Tool registry, quyền từng hành động, sandbox code và contract đầu ra có kiểm chứng.'],['P1','Phục hồi và kiểm soát chi phí','Chưa kiểm thử bằng API thật vì không có key được cấu hình.','Queue bền vững, budget hard-stop, backoff, circuit breaker, retry từng nhánh và idempotency.'],['P2','Tổ chức quanh nhiệm vụ thay vì danh sách agent','Office hiển thị nhiều hồ sơ dài; khó thấy sản phẩm công việc ở cái nhìn đầu.','Mission Control, hàng chờ cần duyệt, artifact preview và tìm kiếm xuyên phòng ban.']];
function review(){return heading('PRODUCT REVIEW','Từ demo hấp dẫn đến công cụ tin cậy.','Nhận xét từ quan sát giao diện và một lượt chạy Demo; không phải kiểm toán backend.')+`<div class="notice">Đã quan sát: Office, Bảng Việc, Thống Kê, Agent Thoughts, Chi Phí, Bảo Mật, Cài Đặt; thử tạo nhiệm vụ thiếu nội dung và Test Gemini không có key. Chưa kiểm chứng API thật, upload/parser, lưu trữ bền vững, phân quyền, quét mạng hoặc tích hợp Drive.</div><div class="card"><h2>Ưu tiên bổ sung</h2>${findings.map((f,i)=>`<div class="row" style="align-items:flex-start">${pill(f[0],f[0]==='P0'?'red':f[0]==='P1'?'orange':'blue')}<div class="row-content"><h3>${f[1]}</h3><p class="hint">${f[2]}</p><p style="font-size:12px;margin-bottom:0"><strong>Đề xuất:</strong> ${f[3]}</p></div></div>`).join('')}</div><div class="grid section"><div class="card"><h2>Lộ trình triển khai</h2>${[['Chặng 1 · Tính đúng','Demo/Live, validation, artifact thật, usage thật và bằng chứng QA.'],['Chặng 2 · Tính bền','Backend secrets, ACL, queue, retry, ngân sách và lịch sử phiên bản.'],['Chặng 3 · Tạo giá trị','Tích hợp CRM/Drive, xuất file, workflow liên phòng và bộ đánh giá chuẩn.']].map(x=>`<div class="step"><div><h3>${x[0]}</h3><p>${x[1]}</p></div></div>`).join('')}</div><div class="card"><h2>Quan điểm thiết kế</h2><p>Thêm nhiều API không tự tạo ra nhiều giá trị. Giá trị đến từ việc hoàn tất một nhiệm vụ đúng, kiểm tra được và đưa kết quả vào công việc thật.</p><p class="muted">Ưu tiên 3 quy trình chạy tốt trước: chiến dịch marketing, đối soát chứng từ mẫu, và tiếp nhận khách hàng. Mỗi quy trình cần bộ dữ liệu chuẩn và tiêu chí đạt rõ ràng.</p><button id="report">↓ Tải đánh giá & đề xuất</button></div></div>`}
function download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{if(state.phase===1||state.phase===2){toast('Chờ lượt mô phỏng hiện tại hoàn tất.');return}state.scenario=b.dataset.scenario;state.draft=null;state.phase=0;state.approved=false;go('missions')});document.querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>{const a=agents[+b.dataset.agent];modal(a[0]+' · '+a[1],`${a[2]}\n\nCông cụ đề xuất: ${a[3]}.\nQuyền: chỉ đọc tài liệu được giao; chỉ tạo bản nháp trong workspace.\nKhông có quyền: đọc toàn bộ kho, xem secret, tự gửi email, tự chi tiền hoặc phê duyệt hành động của chính mình.\n\nĐầu ra bắt buộc: nội dung, nguồn, giả định, trạng thái kiểm chứng và lỗi còn mở.\nDữ liệu log: model thực tế, thời lượng, usage, tool calls, retry và phiên bản artifact.\nBản này chỉ mô phỏng cấu hình; chưa kết nối provider.`)});document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>{const k=Object.keys(docs)[+b.dataset.doc];modal(k,docs[k])});$('#brief')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const title=f.get('title').trim(),goal=f.get('goal').trim(),expected=f.get('expected').trim(),budget=Number(f.get('budget'));if(!title||!goal||!expected)return toast('Cần tên, mục tiêu và đầu ra nghiệm thu.');if(budget<.42)return toast('Trần thấp hơn chi phí kịch bản $0.42. Tăng trần hoặc thu hẹp tác vụ.');state.draft={title,goal,expected,budget};state.fault=f.get('fault');state.fixed=false;state.approved=false;state.phase=1;render();setTimeout(()=>{state.phase=2;render();setTimeout(()=>{state.phase=3;render();toast('Quy trình có điểm chặn cần xử lý.')},1600)},1200)});$('#fix')?.addEventListener('click',()=>{if(state.fault!=='none'&&!state.fixed){state.fixed=true;render();toast('Đã xử lý lỗi giả lập. Tiếp theo: vòng kiểm định QA.');return}state.phase=4;render();toast('Đã hoàn tất mô phỏng. Chờ bạn duyệt bản nháp.')});$('#files')?.addEventListener('change',e=>{state.files=Array.from(e.target.files).map(f=>({name:f.name,size:f.size}));render()});$('#approve')?.addEventListener('click',()=>{state.approved=true;render();toast('Đã duyệt bản nháp trong sandbox. Không có hành động bên ngoài.')});$('#reject')?.addEventListener('click',()=>{state.phase=3;state.fault='none';state.approved=false;go('missions');toast('Đã trả lại vòng QA để minh họa sửa lại.')});$('#export')?.addEventListener('click',()=>download('kcc-ai-office-goi-mo-phong.md','# KCC AI Office · Gói kết quả mô phỏng\n\nKhông phải kết quả API thật.\n\n'+Object.entries(docs).map(([k,v])=>'## '+k+'\n\n'+v).join('\n\n---\n\n')));$('#report')?.addEventListener('click',()=>download('kcc-ai-office-danh-gia.md','# Đánh giá AI Office\n\nPhạm vi: kiểm tra giao diện và một run Demo, không kiểm toán backend.\n\n'+findings.map(f=>`## ${f[0]} · ${f[1]}\n${f[2]}\n\nĐề xuất: ${f[3]}`).join('\n\n')))}
$('#detail .close').onclick=()=>$('#detail').close();render();
